import { Meta, StoryObj } from "@storybook/react";
import { Icon, iconNames, iconSizes } from "./icon";
import styles from "./icon.stories.module.less";
import { ShowcaseLayout, Variant, desktopOnlyMode, showcaseParameters } from "@/storybook/preview";

const meta = {
  title: "Primitives/Icon",
  component: Icon,
  parameters: {
    chromatic: desktopOnlyMode,
    docs: {
      description: {
        component:
          "Renders one of the icons in `iconMap` by name: mostly Material rounded icons, plus a few custom " +
          "ones. The icon is sized through the `size` prop or inherits the surrounding font size, and takes " +
          "its color from the current text color. To add an icon, import it from `@mui/icons-material` and " +
          "add it to `iconMap` (see the comment at the top of icon.tsx).",
      },
    },
  },
  argTypes: {
    "data-testid": { table: { disable: true } },
  },
  args: {
    name: "add",
    size: undefined,
    className: undefined,
  },
} satisfies Meta<typeof Icon>;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = {};

export const VariantSizes: Story = {
  parameters: showcaseParameters,
  args: {
    name: "clock",
  },
  render: (args) => (
    <ShowcaseLayout title="size" variantType="prop">
      <Variant label="undefined (inherits font size)">
        <Icon {...args} size={undefined} />
      </Variant>
      {iconSizes.map((size) => (
        <Variant key={size} label={size}>
          <Icon {...args} size={size} />
        </Variant>
      ))}
    </ShowcaseLayout>
  ),
};

export const VariantAllIcons: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="name (every icon in iconMap)" variantType="prop">
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(12rem, 1fr))", gap: "1rem" }}>
        {[...iconNames].sort().map((name) => (
          <div key={name} style={{ display: "flex", gap: "0.5rem", alignItems: "center" }}>
            <Icon {...args} name={name} size="l" />
            <code>{name}</code>
          </div>
        ))}
      </div>
    </ShowcaseLayout>
  ),
};

export const VariantClassName: Story = {
  parameters: showcaseParameters,
  render: (args) => (
    <ShowcaseLayout title="className" variantType="prop">
      <Variant label="undefined">
        <Icon {...args} />
      </Variant>
      <Variant label="custom class (red, 4rem)">
        <Icon {...args} className={styles.customIconStyling} />
      </Variant>
    </ShowcaseLayout>
  ),
};
